-- 3. Every catalogue exercise's details, guide and setup.
update public.exercises e
set slug = v.slug,
    muscle_group = v.muscle::public.muscle_group,
    equipment = v.equipment,
    measurement_type = v.measure::public.measurement_type,
    movement_type = v.movement::public.movement_type,
    logging_style = v.logging::public.logging_style,
    secondary_muscle_groups = v.secondary::public.muscle_group[],
    movement_pattern = v.pattern,
    instructions = v.summary,
    setup_steps = v.setup,
    execution_steps = v.steps,
    common_mistakes = v.mistakes,
    search_aliases = v.aliases,
    grip = v.grip,
    attachment = v.attachment,
    pulley_position = v.pulley,
    load_type = v.load,
    is_active = v.active
from (values
  ('Dumbbell Bench Press', 'db-bench-press', 'chest', 'dumbbell', 'weight_reps', 'bilateral', null, array['shoulders', 'triceps'], 'horizontal_push', 'A flat-bench press that lets each arm move freely, for a deep stretch across the chest.', array['Sit on the end of a flat bench with a dumbbell on each thigh, then lie back and bring them to the sides of your chest.', 'Plant your feet, squeeze your shoulder blades together and keep a slight arch in your upper back.']::text[], array['Press the dumbbells up over your chest until your arms are straight, bringing them a little closer together at the top.', 'Lower them slowly to the sides of your chest, elbows about 45 degrees from your body.', 'Pause for a moment at the bottom, then press again.']::text[], array['Flaring the elbows straight out to the sides, which strains the shoulders.', 'Bouncing out of the bottom instead of controlling the stretch.', 'Letting the shoulders roll forward off the bench at the top.']::text[], array['flat dumbbell press', 'db bench']::text[], null, null, null, null, true),
  ('Incline Dumbbell Bench Press', 'db-incline-bench-press', 'chest', 'dumbbell', 'weight_reps', 'bilateral', null, array['shoulders', 'triceps'], 'horizontal_push', 'A dumbbell press on a bench set to about 30 degrees, putting more of the work on the upper chest.', array['Set the bench to 30 to 45 degrees and lie back with the dumbbells at the sides of your upper chest.', 'Keep your feet flat and your shoulder blades pulled back into the bench.']::text[], array['Press the dumbbells up and slightly back until they are over your shoulders.', 'Lower them under control to the sides of your upper chest.', 'Keep your wrists stacked over your elbows the whole way.']::text[], array['Setting the bench so steep that it becomes a shoulder press.', 'Arching the lower back to push the chest up.', 'Letting the dumbbells drift down toward the stomach.']::text[], array['incline dumbbell press', 'incline db press']::text[], null, null, null, null, true),
  ('Decline Dumbbell Bench Press', 'db-decline-bench-press', 'chest', 'dumbbell', 'weight_reps', 'bilateral', null, array['shoulders', 'triceps'], 'horizontal_push', 'A dumbbell press on a decline bench, working the lower part of the chest.', array['Hook your legs under the pads of a decline bench and lie back with the dumbbells at the sides of your lower chest.', 'Pull your shoulder blades back and keep your head on the bench.']::text[], array['Press the dumbbells up until your arms are straight over your lower chest.', 'Lower them slowly back to the sides of your lower chest.', 'Breathe out as you press.']::text[], array['Getting into position without help, which is hard with heavy dumbbells.', 'Lowering the dumbbells toward the neck instead of the lower chest.', 'Rushing the lowering phase.']::text[], array['decline dumbbell press', 'decline db press']::text[], null, null, null, null, true),
  ('Dumbbell Chest Fly', 'db-chest-fly', 'chest', 'dumbbell', 'weight_reps', 'bilateral', null, array['shoulders', 'biceps'], 'fly', 'A wide arcing movement on a flat bench that stretches and squeezes the chest without much help from the triceps.', array['Lie on a flat bench with the dumbbells pressed up over your chest, palms facing each other.', 'Bend your elbows slightly and keep that bend for the whole set.']::text[], array['Open your arms in a wide arc, lowering the dumbbells out to the sides until you feel a stretch across your chest.', 'Bring them back up along the same arc, as if hugging a large tree.', 'Squeeze your chest as the dumbbells meet over you.']::text[], array['Bending and straightening the elbows, which turns it into a press.', 'Lowering past the point your shoulders can control.', 'Using weights too heavy to keep the arc smooth.']::text[], array['dumbbell fly', 'flat fly', 'db fly']::text[], null, null, null, null, true),
  ('Incline Dumbbell Chest Fly', 'db-incline-chest-fly', 'chest', 'dumbbell', 'weight_reps', 'bilateral', null, array['shoulders', 'biceps'], 'fly', 'A chest fly on a bench set to about 30 degrees, emphasising the upper chest.', array['Set the bench to about 30 degrees and lie back with the dumbbells over your upper chest, palms facing.', 'Keep a soft bend in your elbows.']::text[], array['Lower the dumbbells out to the sides in a wide arc until your chest is stretched.', 'Bring them back together over your upper chest along the same path.', 'Squeeze at the top before the next rep.']::text[], array['Straightening the arms fully, which loads the elbows.', 'Dropping too deep and stressing the front of the shoulders.', 'Letting the dumbbells clang together at the top.']::text[], array['incline dumbbell fly', 'incline fly']::text[], null, null, null, null, true),
  ('Decline Dumbbell Chest Fly', 'db-decline-chest-fly', 'chest', 'dumbbell', 'weight_reps', 'bilateral', null, array['shoulders', 'biceps'], 'fly', 'A chest fly on a decline bench, working the lower chest through a wide arc.', array['Secure your legs on a decline bench and lie back with the dumbbells over your lower chest, palms facing.', 'Keep your elbows slightly bent.']::text[], array['Open your arms out to the sides until you feel a stretch across your lower chest.', 'Sweep the dumbbells back up and together over your lower chest.', 'Control every rep; do not let gravity take over at the bottom.']::text[], array['Turning the fly into a press by bending the elbows more.', 'Lowering the weights below shoulder level.', 'Lifting the head off the bench.']::text[], array['decline dumbbell fly', 'decline fly']::text[], null, null, null, null, true),
  ('Dumbbell Squeeze Press', 'db-squeeze-press', 'chest', 'dumbbell', 'weight_reps', 'bilateral', null, array['shoulders', 'triceps'], 'horizontal_push', 'A flat press with the dumbbells squeezed together the whole time, keeping the chest working hard.', array['Lie on a flat bench and hold the dumbbells together over your chest, palms facing each other.', 'Press the dumbbells hard into each other.']::text[], array['Keeping them squeezed together, lower the dumbbells to the middle of your chest.', 'Press them back up, still pushing them into each other.', 'Keep the squeeze for every rep of the set.']::text[], array['Letting the dumbbells drift apart, which takes the tension off the chest.', 'Lowering to the neck instead of mid-chest.', 'Going too heavy to keep the squeeze.']::text[], array['crush press', 'hex press']::text[], null, null, null, null, true),
  ('Dumbbell Pullover', 'db-pullover', 'chest', 'dumbbell', 'weight_reps', 'bilateral', null, array['back', 'triceps', 'core'], 'pullover', 'One dumbbell taken from over the chest to behind the head and back, stretching the chest and lats.', array['Lie on a flat bench and hold one dumbbell over your chest with both hands cupping the top plate.', 'Bend your elbows slightly and brace your stomach.']::text[], array['Lower the dumbbell in an arc back over your head until your upper arms are level with your ears.', 'Pull it back over your chest along the same arc.', 'Keep your elbow bend the same throughout.']::text[], array['Bending the elbows more as you lower, which turns it into a triceps extension.', 'Arching the lower back to go deeper.', 'Going too heavy and losing control behind the head.']::text[], array['db pullover']::text[], null, null, null, null, true),
  ('Dumbbell Bent-Over Row', 'db-bent-over-row', 'back', 'dumbbell', 'weight_reps', 'bilateral', null, array['shoulders', 'biceps'], 'horizontal_pull', 'Both dumbbells rowed toward the hips from a hinged position, building the whole upper back.', array['Hold a dumbbell in each hand, soften your knees and hinge forward until your torso is about 45 degrees from the floor.', 'Let the dumbbells hang under your shoulders, palms facing each other, back flat.']::text[], array['Pull the dumbbells toward your hips, driving your elbows back past your body.', 'Squeeze your shoulder blades together at the top.', 'Lower the dumbbells slowly until your arms are straight.']::text[], array['Rounding the back instead of keeping it flat.', 'Standing up taller with every rep.', 'Shrugging the dumbbells up to the ears instead of pulling with the back.']::text[], array['two-arm dumbbell row', 'db row']::text[], null, null, null, null, true),
  ('Single-Arm Dumbbell Row', 'db-single-arm-row', 'back', 'dumbbell', 'weight_reps', 'unilateral', 'single_side', array['shoulders', 'biceps'], 'horizontal_pull', 'One arm at a time with the other hand and knee on a bench, so the back can pull through a long range.', array['Put your left knee and left hand on a flat bench, with your right foot on the floor out to the side.', 'Hold the dumbbell in your right hand with your arm straight under your shoulder and your back flat.']::text[], array['Pull the dumbbell up toward your hip, keeping your elbow close to your side.', 'Stop when your elbow passes your torso and squeeze your back.', 'Lower it slowly until your arm is straight, then switch sides after the set.']::text[], array['Twisting the torso open to heave the weight up.', 'Pulling to the chest instead of the hip.', 'Letting the shoulder drop toward the floor at the bottom without control.']::text[], array['one-arm dumbbell row', 'one arm row', 'bench row']::text[], null, null, null, null, true),
  ('Chest-Supported Dumbbell Row', 'db-chest-supported-row', 'back', 'dumbbell', 'weight_reps', 'bilateral', null, array['shoulders', 'biceps'], 'horizontal_pull', 'A row lying face-down on an incline bench, so the back works without the lower back or momentum helping.', array['Set a bench to about 30 degrees and lie face-down on it with your chest on the pad and your feet on the floor.', 'Let the dumbbells hang straight down below your shoulders.']::text[], array['Row the dumbbells up toward your lower ribs, elbows travelling back.', 'Squeeze your shoulder blades together at the top.', 'Lower them under control until your arms are straight.']::text[], array['Lifting the chest off the pad to cheat the weight up.', 'Shrugging the shoulders toward the ears.', 'Cutting the range short at the bottom.']::text[], array['incline bench dumbbell row', 'incline dumbbell row', 'seal row dumbbell']::text[], null, null, null, null, true),
  ('Dumbbell Renegade Row', 'db-renegade-row', 'back', 'dumbbell', 'weight_reps', 'bilateral', null, array['biceps', 'triceps', 'core'], 'horizontal_pull', 'A row from the top of a push-up, alternating arms while the core keeps the hips still.', array['Get into a high plank with your hands on two dumbbells, wrists under your shoulders.', 'Spread your feet a little wider than your hips for balance and brace your stomach.']::text[], array['Row one dumbbell up toward your hip while pressing the other into the floor.', 'Lower it back down with control.', 'Repeat on the other side without letting your hips twist.']::text[], array['Letting the hips rotate or sag with each row.', 'Using dumbbells that roll; hexagonal ones are safer.', 'Rushing so the plank position falls apart.']::text[], array['plank row']::text[], null, null, null, null, true),
  ('Dumbbell Rear Delt Fly', 'db-rear-delt-fly', 'shoulders', 'dumbbell', 'weight_reps', 'bilateral', null, array['back'], 'raise', 'A bent-over fly that raises the dumbbells out to the sides, targeting the backs of the shoulders.', array['Hold the dumbbells and hinge forward until your torso is nearly parallel to the floor, knees soft.', 'Let the dumbbells hang under your chest with palms facing and a slight bend in your elbows.']::text[], array['Raise the dumbbells out to the sides until your arms are level with your body.', 'Pause and squeeze the backs of your shoulders.', 'Lower them slowly back under your chest.']::text[], array['Swinging the torso up to lift the weight.', 'Squeezing the shoulder blades so hard the upper back takes over.', 'Using weights too heavy to raise with straight-ish arms.']::text[], array['dumbbell reverse fly', 'reverse fly', 'bent-over dumbbell rear delt raise', 'rear delt raise', 'bent-over reverse fly']::text[], null, null, null, null, true),
  ('Incline Dumbbell Rear Delt Fly', 'db-incline-rear-delt-fly', 'shoulders', 'dumbbell', 'weight_reps', 'bilateral', null, array['back'], 'raise', 'A rear delt fly lying face-down on an incline bench, so the shoulders work without any swinging.', array['Lie face-down on a bench set to about 30 degrees, chest on the pad.', 'Let the dumbbells hang below your shoulders, palms facing, elbows slightly bent.']::text[], array['Raise the dumbbells out to the sides in a wide arc until your arms are level with the bench.', 'Hold for a second at the top.', 'Lower them slowly back down.']::text[], array['Lifting the chest off the bench.', 'Bending the elbows more to row the weight up.', 'Dropping the dumbbells quickly on the way down.']::text[], array['incline dumbbell reverse fly', 'incline reverse fly', 'chest-supported rear delt fly']::text[], null, null, null, null, true),
  ('Dumbbell Shrug', 'db-shrug', 'back', 'dumbbell', 'weight_reps', 'bilateral', null, array['forearms'], 'shrug', 'Lifting the shoulders straight up toward the ears with dumbbells at the sides, building the upper traps.', array['Stand tall with a dumbbell in each hand at your sides, palms facing in.', 'Keep your arms straight and your chest up.']::text[], array['Raise your shoulders straight up toward your ears as high as you can.', 'Hold for a second at the top.', 'Lower them all the way down slowly.']::text[], array['Rolling the shoulders in circles, which adds nothing.', 'Bending the elbows to help lift.', 'Bobbing through short reps with too much weight.']::text[], array['dumbbell shrugs', 'db shrug']::text[], null, null, null, null, true),
  ('Dumbbell Deadlift', 'db-deadlift', 'back', 'dumbbell', 'weight_reps', 'bilateral', null, array['forearms', 'quadriceps', 'hamstrings', 'glutes'], 'hinge', 'A deadlift with a dumbbell in each hand, lifting from just above the floor to standing tall.', array['Stand with your feet hip-width apart and the dumbbells on the floor beside your feet.', 'Bend your hips and knees to grip them with a flat back, chest up and arms straight.']::text[], array['Push the floor away and stand up, keeping the dumbbells close to your legs.', 'Finish tall with your hips through and shoulders back.', 'Hinge at the hips and bend your knees to lower them back to the floor.']::text[], array['Rounding the lower back at the bottom.', 'Letting the dumbbells drift forward away from the body.', 'Leaning back at the top instead of standing straight.']::text[], array['db deadlift']::text[], null, null, null, null, true),
