  ('Dumbbell Stiff-Leg Deadlift', 'db-stiff-leg-deadlift', 'hamstrings', 'dumbbell', 'weight_reps', 'bilateral', null, array['back', 'forearms', 'glutes'], 'hinge', 'A hinge with the legs almost straight, lowering the dumbbells further for a deep hamstring stretch.', array['Stand with your feet hip-width apart, dumbbells in front of your thighs.', 'Keep your legs nearly straight with only a tiny bend in the knees.']::text[], array['Hinge at the hips and lower the dumbbells as far as your flexibility allows with a flat back.', 'Feel the stretch in the backs of your legs.', 'Squeeze your glutes to return to standing.']::text[], array['Locking the knees completely.', 'Rounding the back to touch the floor.', 'Going too heavy before you have the flexibility.']::text[], array['dumbbell straight-leg deadlift', 'db sldl']::text[], null, null, null, null, true),
  ('Dumbbell Farmer''s Carry', 'db-farmers-carry', 'back', 'dumbbell', 'timed', 'bilateral', null, array['forearms', 'quadriceps', 'glutes', 'core'], 'carry', 'Walking while holding heavy dumbbells at your sides, building grip, traps and a strong core. Log the time you walk.', array['Pick up a heavy dumbbell in each hand with a flat back, as in a deadlift.', 'Stand tall with your shoulders back and the dumbbells at your sides.']::text[], array['Walk forward with short, steady steps.', 'Keep your chest up and your shoulders level the whole way.', 'Set the dumbbells down with control when the time is up.']::text[], array['Letting the shoulders round forward.', 'Taking long, bouncing strides that swing the weights.', 'Leaning to one side.']::text[], array['farmers walk', 'farmer walk', 'farmers carry']::text[], null, null, null, null, true),
  ('Dumbbell Suitcase Carry', 'db-suitcase-carry', 'core', 'dumbbell', 'timed', 'unilateral', 'single_side', array['back', 'forearms'], 'carry', 'Walking with one heavy dumbbell on one side, so the core works to keep you from leaning. Log the time for each side.', array['Hold one heavy dumbbell at your side like a suitcase.', 'Stand tall with your shoulders level and stomach braced.']::text[], array['Walk forward with steady steps, resisting the pull to lean toward the weight.', 'Keep both shoulders level and your free arm relaxed.', 'Switch hands and repeat for the same time.']::text[], array['Leaning away from the dumbbell to counterbalance.', 'Shrugging the loaded shoulder up.', 'Rushing so the weight swings.']::text[], array['suitcase walk', 'single-arm farmers carry']::text[], null, null, null, null, true),
